ename'), ('document', 'mime_type'), ('document', 'size_bytes'), ('document', 'purpose'), ('document', 'is_cover'), ('document', 'sort_order'), ('document', 'owner_user_id'), ('document', 'product_id'), ('document', 'order_stage_event_id'), ('document', 'producer_id'), ('document', 'created_at'), ('document', 'deleted_at'), ('document', 'product_variant_id'), ('document', 'project_quote_id'), ('document', 'product_option_id'), ('document', 'floor_level')) AS r(t, c)
  WHERE NOT EXISTS (
    SELECT 1 FROM information_schema.columns k
    WHERE k.table_schema = 'public' AND k.table_name = r.t AND k.column_name = r.c
  );
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'Na tej bazie brakuje kolumn (najpierw wdróż migrację 0070 i wcześniejsze): %', missing;
  END IF;
  IF EXISTS (SELECT 1 FROM producer WHERE nip = '5423465217' AND id <> 'e0030000-0000-4000-8000-000000000110') THEN
    RAISE EXCEPTION 'NIP roboczy jest już zajęty przez inny wiersz, przerywam';
  END IF;
  IF EXISTS (SELECT 1 FROM product WHERE slug IN ('malta', 'madera', 'sylt', 'sky-light', 'silver-moon', 'moon-light', 'vario-3br', 'zen', 'bali', 'malibu', 'bremen', 'palermo', 'riviera', 'nicea', 'elba', 'black-stone', 'vario-2br') AND producer_id <> 'e0030000-0000-4000-8000-000000000110') THEN
